import json
import glob
import os

WORKDIR = os.path.dirname(os.path.abspath(__file__))
FILES = sorted(glob.glob(os.path.join(WORKDIR, "sales_2026-*.csv")))

REQUIRED = ("region", "sku", "qty", "unit_price")

def load(path):
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        cols = [c.lower().strip() for c in reader.fieldnames]
        missing = [r for r in REQUIRED if r not in cols]
        if missing:
            raise SystemExit(f"{path}: missing required columns {missing}; found {cols}")
        idx = {r: cols.index(r) for r in REQUIRED}
        month = path.rsplit("/", 1)[0].rsplit("_", 1)[1][:7]  # 2026-05
        rows_used = 0
        skipped = 0
        month_rev = 0.0
        region_rev = {}
        for raw in reader:
            region = raw[idx["region"]].strip()
            qty = raw[idx["qty"]].strip()
            price = float(raw[idx["unit_price"]])
            if qty == "":
                skipped += 1
                continue
            qty = float(qty)
            revenue = qty * price
            month_rev += revenue
            region_rev[region] = region_rev.get(region, 0.0) + revenue
            rows_used += 1
        return month, rows_used, skipped, month_rev, region_rev

months = {}
total_skipped = 0
grand_region = {}

for path in FILES:
    month, rows_used, skipped, rev, region_rev = load(path)
    months[month] = {"rows_used": rows_used, "revenue": round(rev, 2)}
    total_skipped += skipped
    for r, v in region_rev.items():
        grand_region[r] = grand_region.get(r, 0.0) + v

top_region = max(grand_region.items(), key=lambda kv: kv[1])
summary = {
    "months": months,
    "skipped_rows": total_skipped,
    "top_region": {"region": top_region[0], "revenue": round(top_region[1], 2)},
}

with open(os.path.join(WORKDIR, "summary.json"), "w") as f:
    json.dump(summary, f, indent=2)

print(json.dumps(summary, indent=2))
print(f"\nFiles processed: {len(FILES)} | total rows_used: {sum(m['rows_used'] for m in months.values())} | total data rows scanned: {sum(m['rows_used'] + m['skipped_rows'] for m in months.values())} | skipped: {total_skipped}")
